fields.InputDefinition:
{
  "goal": "Navigate to Data Explorer > Queries. Find and Run a no-parameter Approved query (use the 'Search queries...' sidebar box or a visible folder query like 'Entities with Field Counts'). Once results display in the grid, interact with the results — click a column header to sort, or click a result row — and verify the grid responds. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 45,
  "judgeValidationCriteria": [
    "A no-parameter query was run and results displayed in a grid",
    "Interacting with the results grid (sort or row click) produced a visible response",
    "No error messages, blank screens, or crash pages"
  ]
}
